static HRESULT WINAPI my_GetOutputAvailableType(void *self, DWORD stream,
                                                DWORD index, void **type)
{
    HRESULT hr = real_GetOutputAvailableType(self, stream, index, type);
    if (SUCCEEDED(hr) && type && *type)
    {
        GUID sub;
        if (type_subtype(*type, &sub))
        {
            char label[32];
            snprintf(label, sizeof(label), "offers type %lu", index);
            describe_subtype(label, &sub);

            if (restore_nv12 && !IsEqualGUID(&sub, &guid_MFVideoFormat_NV12))
            {
                static LONG said;
                if (type_set_subtype(*type, &guid_MFVideoFormat_NV12))
                {
                    if (InterlockedIncrement(&said) == 1)
                        logf_("  -> relabelled as NV12, which is what Electra "
                              "requires and what winegstreamer censored");
                }
                else if (InterlockedIncrement(&said) == 1)
                    logf_("  -> could NOT relabel to NV12");
            }
        }
        else
            logf_("  offers type %lu (subtype unreadable)", index);
    }
    else if (hr == 0xC00D36B9L)   /* MF_E_NO_MORE_TYPES */
        logf_("  ...that is all it offers (%lu total). The game picks from "
              "this list, and stops here if none will do.", index);
    else
        logf_("GetOutputAvailableType(%lu) -> 0x%08lx", index, hr);
    return hr;
}

static void force_electra_software(void)
{
    BYTE *base = (BYTE *)GetModuleHandleA(NULL);
    int done = 0;
    if (electra_sw_forced || !base) return;
    electra_sw_forced = TRUE;

    read_switches();
    logf_("putting Electra on its old output path");

    /* The two IsSoftware call sites used to be patched here, by address.
     *
     * They are gone, and nothing is read off a disassembly any more. The
     * software path comes from the engine instead: winegstreamer patch 0006,
     * carried from winevideo, stops advertising MF_SA_D3D_AWARE on macOS, so
     * Electra never builds a D3D11 device and answers its own IsSoftware()
     * honestly. That is in the engine this project ships and it does not move
     * when the game does.
     *
     * Those addresses broke three times in sixteen days -- 2026-08-24,
     * 08-31 and 09-08 -- and each time they took the console variable down
     * with them, because the check refused before reaching it. The variable is
     * found by name and never needed the addresses at all; that coupling was
     * the actual defect, and this is where it ends.
     *
     * Measured 2026-09-09 on UE5-CL-408709: with the variable set and no byte
     * patched anywhere, the video plays. Without the variable the title
     * crashes in the D3D path, EXCEPTION_ACCESS_VIOLATION reading 0x0 -- so
     * patch 0006 alone is not enough and the variable below is load-bearing. */

    /* The console variable is a pointer read from a fixed address and written
     * through -- a wild write on any build but the one it was read from, and
     * that build is gone. Left alone until it is found the same way the calls
     * were. */
    /* The values live at object + 0x50, and that was read off the vtable
     * rather than guessed.
     *
     * What the fixed address holds in this build is an IConsoleVariable, not
     * the two plain ints the old code wrote -- its first qword is a pointer
     * into .rdata, so writing 1 at offset zero would destroy the vtable and
     * produce exactly the null dereference this afternoon was spent chasing.
     *
     * Its vtable says where the data is. Slot 12 is `lea rax,[rcx+0x50] ; ret`
     * -- AsVariableInt returning the embedded TConsoleVariableData<int32> --
     * and slot 8 is `mov al,1 ; ret`, which is the "this is an int variable"
     * answer. So the two int32s the old build had at offset zero are at 0x50
     * here, and the old write is right about what to set and wrong only about
     * where.
     *
     * Read before writing anyway: the default is 0, so anything else means
     * this is not what it is thought to be, and then nothing is touched. */
    {
        void **slot = find_cvar_slot(base);
        void *obj;
        if (!slot)
        {
            /* There is no falling back to a remembered address any more. What
             * made that safe was the call-site check proving this was the build
             * the address came from, and that check is gone. A remembered
             * address on a build it was not read from is a wild write. */
            logf_("  the console variable was not found by name -- doing nothing");
            return;
        }
        obj = *slot;
        if (!obj)
        {
            logf_("  console variable not registered yet");
        }
        else
        {
            int *values = (int *)((BYTE *)obj + CVAR_VALUES_OFFSET);
            logf_("  console variable at %p, values at +0x%X currently [%d, %d]",
                  obj, (unsigned)CVAR_VALUES_OFFSET, values[0], values[1]);
            if (!opt_cvar)
                logf_("    left at [%d, %d], by switch -- Electra keeps whichever "
                      "output path it chooses for itself", values[0], values[1]);
            else if (values[0] == 0 && values[1] == 0)
            {
                values[0] = 1;
                values[1] = 1;
                cvar_ready = TRUE;
                logf_("    set to 1 -- Electra takes the old CPU buffer path, "
                      "which stores the sample instead of querying for a D3D "
                      "resource that is not there");
            }
            else
                logf_("    left alone: the default for this variable is 0, so "
                      "this is not the field it is thought to be");
        }
    }

    if (!done) logf_("nothing was patched");
}

static HRESULT WINAPI my_gfx(void *dev, const void *desc, REFIID iid, void **out)
{
    unsigned long long h;
    if (desc && is_hidden(*(void *const *)((const char *)desc + 24), *(const SIZE_T *)((const char *)desc + 32), &h))
    {
        /* sizeof(D3D12_GRAPHICS_PIPELINE_STATE_DESC) on x64: no more is read. */
        char copy[656];
        HRESULT hr;
        memcpy(copy, desc, sizeof(copy));
        mute(copy + 120);
        hr = real_gfx(dev, copy, iid, out);
        InterlockedIncrement(&muted);
        logline("interiorPS %016llx hidden (graphics) -> %08lx", h, (unsigned long)hr);
        return hr;
    }
    return real_gfx(dev, desc, iid, out);
}

static void mute(char *blend)
{
    int i;
    for (i = 0; i < 8; i++) ((unsigned char *)blend)[8 + i * 40 + 36] = 0;
}

static HRESULT WINAPI my_create(void *stream, void *attrs, void **reader)
{
    static LONG calls, ours;
    HRESULT hr = real_create(stream, attrs, reader);
    LONG n = InterlockedIncrement(&calls);
    if (n == 1) logf_("MFCreateSourceReaderFromByteStream -> 0x%08lx (first call)", hr);
    if (FAILED(hr) && stream && reader && load_asf_reader_())
    {
        HRESULT mine = asf_reader_create(stream, attrs, reader);
        LONG k = InterlockedIncrement(&ours);
        if (k <= 5 || FAILED(mine))
            logf_("Media Foundation refused a stream (0x%08lx); our ASF reader -> 0x%08lx (%ld so far)",
                  hr, mine, k);
        if (SUCCEEDED(mine)) hr = mine;
    }
    return hr;
}

static HRESULT WINAPI d3d12_open_shared_handle(void *self, HANDLE handle,
                                               REFIID iid, void **out)
{
    {
        static LONG told;
        if (InterlockedIncrement(&told) <= 12)
            logf_("D3D12 OpenSharedHandle %p %s%s", handle, guid_text_(iid),
                  handle == BRIDGE_HANDLE ? "   << ours" : "");
    }
    if (handle == BRIDGE_HANDLE)
    {
        HRESULT hr;
        if (!out) return E_INVALIDARG;
        *out = NULL;
        if (!IsEqualGUID(iid, &IID_ID3D12Resource)) return E_NOINTERFACE;

        EnterCriticalSection(&frame_lock);
        /* A new clip of another size: the game has made a new texture and is
         * opening it now, so this is the one moment the bridge can change size.
         * Handing back the old one leaves the game drawing from a texture no
         * frame of this clip can be written into. */
        if (bridge_texture && frame_width && frame_height &&
            (texture_width != frame_width || texture_height != frame_height))
        {
            logf_("bridge: the game opens a %ux%u clip on a %ux%u bridge; rebuilding",
                  frame_width, frame_height, texture_width, texture_height);
            bridge_destroy();
        }
        if (!bridge_texture && frame_width && frame_height)
        {
            /*
             * The size the game asked to share, when it said one.
             *
             * The handle it passes belongs to a texture it created itself, and
             * what comes back has to describe that texture -- not the clip.
             * Kingdom Hearts shares a 2048x1080 surface to carry a 1920x1080
             * frame, so a texture built to the clip's size is the wrong
             * resource under the same handle, and what the game copies out of
             * it is not a picture.
             */
            bridge_create((ID3D12Device *)self, frame_width, frame_height);
        }
        hr = bridge_texture ? S_OK : E_FAIL;
        if (bridge_texture)
        {
            ID3D12Resource_AddRef(bridge_texture);
            *out = bridge_texture;
        }
        LeaveCriticalSection(&frame_lock);
        return hr;
    }
    return real_open_shared_handle(self, handle, iid, out);
}

static HRESULT WINAPI res_get_shared_handle(void *self, HANDLE *handle)
{
    HRESULT hr = real_res_get_shared_handle(self, handle);
    {
        static LONG told;
        if (InterlockedIncrement(&told) <= 12)
            logf_("GetSharedHandle -> 0x%08lx%s", (unsigned long)hr,
                  (FAILED(hr) && d3d12_bridge_armed) ? "   (answering BRIDGE_HANDLE)" : "");
    }
    /*
     * Only invent a handle if the side that can recognise it is armed.
     *
     * BRIDGE_HANDLE is meaningful to d3d12_open_shared_handle and to nothing
     * else. Handing it out while that hook is missing turns a clean failure --
     * the game learns it cannot share, and says so -- into a real D3D12 device
     * dereferencing 0xD3D12B21D. Nioh 3 crashed exactly that way, because its
     * D3D12 arrives through Streamline and the hook had not been placed there
     * yet. Reporting the original failure is the safe answer.
     */
    if (FAILED(hr) && handle && d3d12_bridge_armed) { *handle = BRIDGE_HANDLE; return S_OK; }
    return hr;
}

static uint8_t *find_wrapper(char *why, size_t cap)
{
    static const char name[] = "scePadSetTriggerEffect";
    IMAGE_NT_HEADERS64 *nt = (IMAGE_NT_HEADERS64 *)(g_exe + ((IMAGE_DOS_HEADER *)g_exe)->e_lfanew);
    IMAGE_SECTION_HEADER *sec = IMAGE_FIRST_SECTION(nt);
    IMAGE_DATA_DIRECTORY *exc = &nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXCEPTION];
    const IMAGE_RUNTIME_FUNCTION_ENTRY *fn = (const IMAGE_RUNTIME_FUNCTION_ENTRY *)(g_exe + exc->VirtualAddress);
    size_t nfn = exc->Size / sizeof(*fn), lo, hi;
    uint8_t *text = NULL, *found = NULL, *s;
    uint32_t text_size = 0, str_rva = 0, i, k;
    int strings = 0, hits = 0;

    for (k = 0; k < nt->FileHeader.NumberOfSections; k++)
    {
        uint8_t *b = g_exe + sec[k].VirtualAddress;
        uint32_t n = sec[k].Misc.VirtualSize;
        if (!memcmp(sec[k].Name, ".text", 6)) { text = b; text_size = n; continue; }
        if (sec[k].Characteristics & IMAGE_SCN_MEM_EXECUTE || !(sec[k].Characteristics & IMAGE_SCN_MEM_READ)) continue;
        for (s = b + 1; s + sizeof(name) <= b + n; s++)
            if (*s == name[0] && !s[-1] && !memcmp(s, name, sizeof(name)))
            {
                strings++;
                str_rva = (uint32_t)(s - g_exe);
            }
    }
    if (strings != 1 || !text || !nfn)
    {
        snprintf(why, cap, "%d copies of the name, %s, %u functions", strings, text ? ".text" : "no .text", (unsigned)nfn);
        return NULL;
    }
    for (i = 0; i + 7 <= text_size; i++)
    {
        uint8_t *at = text + i, *start;
        uint32_t rva;
        int32_t disp;
        if ((at[0] != 0x48 && at[0] != 0x4c) || at[1] != 0x8d || (at[2] & 0xc7) != 0x05) continue;
        memcpy(&disp, at + 3, 4);
        rva = (uint32_t)(at + 7 - g_exe) + (uint32_t)disp;
        if (rva != str_rva) continue;
        rva = (uint32_t)(at - g_exe);
        for (lo = 0, hi = nfn; lo < hi; )
        {
            size_t mid = (lo + hi) / 2;
            if (fn[mid].BeginAddress <= rva) lo = mid + 1; else hi = mid;
        }
        if (!lo || rva >= fn[lo - 1].EndAddress) continue;
        start = g_exe + fn[lo - 1].BeginAddress;
        if (memcmp(start, wrapper_start, sizeof(wrapper_start))) continue;
        hits++;
        found = start;
    }
    if (hits != 1)
    {
        snprintf(why, cap, "%d functions name it and start as the wrapper does", hits);
        return NULL;
    }
    return found;
}

static void convert(uint32_t mode, const uint8_t *p, uint8_t out[11])
{
    uint8_t s[10] = {0};
    int i;
    switch (mode)
    {
    case MODE_FEEDBACK:      /* position 0-9, strength 1-8 */
        for (i = p[0]; i < 10; i++) s[i] = p[1];
        zones(s, 0x21, 0, out);
        return;
    case MODE_WEAPON:        /* start 2-7, end start+1-8, strength 1-8 */
        memset(out, 0, 11);
        if (p[0] > 9 || p[1] > 9 || p[1] <= p[0] || !p[2] || p[2] > 8) { out[0] = 0x05; return; }
        out[0] = 0x25;
        out[1] = ((1u << p[0]) | (1u << p[1])) & 0xff;
        out[2] = ((1u << p[0]) | (1u << p[1])) >> 8;
        out[3] = p[2] - 1;
        return;
    case MODE_VIBRATION:     /* position 0-9, amplitude 1-8, frequency in Hz */
        for (i = p[0]; i < 10; i++) s[i] = p[1];
        zones(s, 0x26, p[2], out);
        return;
    case MODE_MULTI_FEEDBACK:  /* strength[10] */
        zones(p, 0x21, 0, out);
        return;
    case MODE_SLOPE:         /* start, end, start strength, end strength */
        if (p[1] > p[0] && p[1] <= 9)
            for (i = p[0]; i < 10; i++)
                s[i] = i >= p[1] ? p[3] : (uint8_t)(p[2] + (int)(p[3] - p[2]) * (i - p[0]) / (p[1] - p[0]));
        zones(s, 0x21, 0, out);
        return;
    case MODE_MULTI_VIBRATION: /* frequency, amplitude[10] */
        zones(p + 1, 0x26, p[0], out);
        return;
    default:
        memset(out, 0, 11);
        out[0] = 0x05;
    }
}

__attribute__((noinline)) int32_t triggers_SetTriggerEffect(int32_t handle, const uint8_t *param)
{
    uint8_t want[2][11];
    int sides = 0, i;
    (void)handle;

    if (!param) return (int32_t)RETURN_NOT_LOADED;
    InterlockedIncrement(&g_effects);
    EnterCriticalSection(&g_lock);
    if (!g_pad_looked) find_pad();
    if (g_pad != INVALID_HANDLE_VALUE)
    {
        /* Sony's command[0] is L2 and command[1] R2; the DualSense's report has R2 first. */
        for (i = 0; i < 2; i++)
        {
            int ds = i ? 0 : 1;
            const uint8_t *cmd = param + CMD_FIRST + CMD_SIZE * i;
            if (!(param[0] & (1 << i))) continue;
            convert(*(const uint32_t *)cmd, cmd + CMD_PARAM, want[ds]);
            if (memcmp(want[ds], g_last[ds], 11) || !g_set[ds])
            {
                if (!g_set[ds] || want[ds][0] != g_last[ds][0])
                    logline("%s: mode %u -> DualSense %02x %02x%02x %02x%02x%02x%02x .. %02x", ds ? "L2" : "R2",
                            *(const uint32_t *)cmd, want[ds][0], want[ds][1], want[ds][2], want[ds][3], want[ds][4],
                            want[ds][5], want[ds][6], want[ds][9]);
                memcpy(g_last[ds], want[ds], 11);
                g_set[ds] = 1;
                sides |= 1 << ds;
            }
        }
        if (sides) write_sides(want, sides);
    }
    LeaveCriticalSection(&g_lock);
    return (int32_t)RETURN_NOT_LOADED;   /* what the original answers: the game behaves as before */
}

static HRESULT STDMETHODCALLTYPE hk_CreateDepthStencilState(ID3D11Device *device,
        const D3D11_DEPTH_STENCIL_DESC *desc, ID3D11DepthStencilState **state)
{
    HRESULT (STDMETHODCALLTYPE *orig)(ID3D11Device *, const D3D11_DEPTH_STENCIL_DESC *, ID3D11DepthStencilState **)
            = orig_fn(device, DEV_IDX(CreateDepthStencilState));
    D3D11_DEPTH_STENCIL_DESC changed;

    if (!desc || !desc->DepthEnable || desc->DepthFunc != D3D11_COMPARISON_EQUAL)
        return orig(device, desc, state);
    if (InterlockedIncrement(&g_equal_seen) <= 16)
        log_msg("EQUAL depth state: depth writes %s, stencil %s%s",
                desc->DepthWriteMask == D3D11_DEPTH_WRITE_MASK_ALL ? "on" : "off",
                desc->StencilEnable ? "on" : "off", g_equal_to ? ", created with the replacement test" : "");
    if (!g_equal_to)
        return orig(device, desc, state);
    changed = *desc;
    changed.DepthFunc = g_equal_to;
    InterlockedIncrement(&g_changed);
    return orig(device, &changed, state);
}

static IMFAttributes *strip_d3d_attributes(IMFAttributes *attrs)
{
    IMFAttributes *plain = NULL;
    UINT32 count = 0;

    if (!attrs || !real_MFCreateAttributes) return NULL;
    IMFAttributes_GetCount(attrs, &count);
    if (SUCCEEDED(real_MFCreateAttributes(&plain, count + 2)) && plain
        && SUCCEEDED(IMFAttributes_CopyAllItems(attrs, plain)))
    {
        IMFAttributes_DeleteItem(plain, &MF_SOURCE_READER_D3D_MANAGER);
        IMFAttributes_DeleteItem(plain, &MF_READWRITE_ENABLE_HARDWARE_TRANSFORMS);
        return plain;
    }
    if (plain) IMFAttributes_Release(plain);
    return NULL;
}

static void plane_write(const BYTE *nv12, UINT stride, UINT width, UINT height)
{
    D3D12_TEXTURE_COPY_LOCATION dst = { 0 }, src = { 0 };
    const BYTE *uv = nv12 + (size_t)stride * height;
    BYTE *mapped = NULL;
    UINT y;

    if (!plane_ready || !bridge_list || !bridge_queue) return;
    /*
     * Copy the planes' geometry, not the frame's.
     *
     * The footprints were computed from the descriptors captured when the pair
     * was created. If a later clip is larger and the game has not yet made a
     * new pair, writing the frame's rows into those footprints runs off the end
     * of the upload buffer. Refusing is the right answer: the next pair the
     * game creates re-arms this.
     */
    if (width != plane_y_desc.Width || height != plane_y_desc.Height) return;
    if (FAILED(ID3D12Resource_Map(plane_upload, 0, NULL, (void **)&mapped)) || !mapped)
        return;
    for (y = 0; y < height; ++y)
        memcpy(mapped + plane_y_fp.Offset + (size_t)y * plane_y_fp.Footprint.RowPitch,
               nv12 + (size_t)y * stride, width);
    for (y = 0; y < height / 2; ++y)
        memcpy(mapped + plane_uv_fp.Offset + (size_t)y * plane_uv_fp.Footprint.RowPitch,
               uv + (size_t)y * stride, width);
    ID3D12Resource_Unmap(plane_upload, 0, NULL);

    ID3D12CommandAllocator_Reset(bridge_alloc);
    ID3D12GraphicsCommandList_Reset(bridge_list, bridge_alloc, NULL);
    src.pResource = plane_upload;
    src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
    dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
    dst.pResource = plane_y;  src.PlacedFootprint = plane_y_fp;
    ID3D12GraphicsCommandList_CopyTextureRegion(bridge_list, &dst, 0, 0, 0, &src, NULL);
    dst.pResource = plane_uv; src.PlacedFootprint = plane_uv_fp;
    ID3D12GraphicsCommandList_CopyTextureRegion(bridge_list, &dst, 0, 0, 0, &src, NULL);
    ID3D12GraphicsCommandList_Close(bridge_list);
    ID3D12CommandQueue_ExecuteCommandLists(bridge_queue, 1,
            (ID3D12CommandList *const *)&bridge_list);

    ++bridge_fence_value;
    if (SUCCEEDED(ID3D12CommandQueue_Signal(bridge_queue, bridge_fence, bridge_fence_value))
        && ID3D12Fence_GetCompletedValue(bridge_fence) < bridge_fence_value
        && bridge_event)
    {
        ID3D12Fence_SetEventOnCompletion(bridge_fence, bridge_fence_value, bridge_event);
        WaitForSingleObject(bridge_event, 1000);
    }
}

