}

static void lower_the_floor(void)
{
    HMODULE base = GetModuleHandleA(NULL);
    IMAGE_DOS_HEADER *dos = (IMAGE_DOS_HEADER *)base;
    IMAGE_NT_HEADERS *nt;
    IMAGE_SECTION_HEADER *sec;
    BYTE *found = NULL;
    int hits = 0;
    unsigned i;

    if (!base || dos->e_magic != IMAGE_DOS_SIGNATURE) return;
    nt = (IMAGE_NT_HEADERS *)((BYTE *)base + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE) return;
    sec = IMAGE_FIRST_SECTION(nt);

    for (i = 0; i < nt->FileHeader.NumberOfSections; i++, sec++)
    {
        BYTE *p, *end;
        if (memcmp(sec->Name, ".text", 5) != 0) continue;
        p   = (BYTE *)base + sec->VirtualAddress;
        end = p + sec->Misc.VirtualSize - sizeof(SM_FLOOR);
        for (; p < end; p++)
        {
            if (p[0] != SM_FLOOR[0] || memcmp(p, SM_FLOOR, sizeof(SM_FLOOR)) != 0) continue;
            if (++hits == 1) found = p;
        }
    }

    if (hits != 1)
    {
        logf_("%d places match the pattern -- leaving all of them alone", hits);
        return;
    }
    {
        DWORD old;
        if (!VirtualProtect(found + 2, 1, PAGE_EXECUTE_READWRITE, &old))
        {
            logf_("VirtualProtect refused (err %lu)", GetLastError());
            return;
        }
        found[2] = 0x66;
        VirtualProtect(found + 2, 1, old, &old);
        logf_("shader model floor 6.7 -> 6.6 at +0x%lX, in memory only%s",
              (unsigned long)(found - (BYTE *)base),
              found[2] == 0x66 ? "" : " -- but the write did not stick");
    }
}

static BOOL refuse(BOOL gs, BOOL ps, UINT so_entries)
{
#ifdef W3_RTPROBE
    if (allow_gs_without_ps && gs && !so_entries && !ps)
    {
        logline("let through geometry-shader pipeline %ld with no pixel shader and no stream output",
                InterlockedIncrement(&let_through));
        return FALSE;
    }
#endif
    return gs && (so_entries || !ps);
}

static HRESULT WINAPI my_gfx(void *dev, const void *desc, REFIID iid, void **out)
{
    const char *d = desc;
    InterlockedIncrement(&seen_gfx);
    if (d && refuse(has_shader(d + 72), has_shader(d + 24), *(const UINT *)(d + 96)))
    {
        LONG n = InterlockedIncrement(&refused);
        logline("refused stream-output pipeline %ld (graphics desc, %u entries)", n, *(const UINT *)(d + 96));
        if (out) *out = NULL;
        return E_INVALIDARG;
    }
#ifdef W3_RTPROBE
    {
        HRESULT hr = real_gfx(dev, desc, iid, out);
        if (FAILED(hr)) logline("CreateGraphicsPipelineState failed: %08lx", (unsigned long)hr);
        return hr;
    }
#else
    return real_gfx(dev, desc, iid, out);
#endif
}

static HRESULT WINAPI my_deserialize(const void *blob, SIZE_T len, REFIID iid, void **out)
{
    if (!has_root_signature(blob, len))
    {
        if (InterlockedIncrement(&refused) <= 8)
            logf_("no RTS0 in a %llu byte container -- answering E_INVALIDARG "
                  "instead of letting it be dereferenced",
                  (unsigned long long)len);
        if (out) *out = NULL;
        return E_INVALIDARG;
    }
    InterlockedIncrement(&passed);
    return real_deserialize(blob, len, iid, out);
}

static HRESULT WINAPI my_modelist(void *self, UINT fmt, UINT flags, UINT *count, void *modes)
{
    HRESULT hr;
    UINT w = 0, h = 0, hz = 0, i, have, room, added = 0, big_w = 0, big_h = 0;

    if (!desktop_size(&w, &h, &hz)) return real_modelist(self, fmt, flags, count, modes);

    if (!modes)                                   /* the counting call */
    {
        hr = real_modelist(self, fmt, flags, count, NULL);
        if (SUCCEEDED(hr) && count) *count += ladder_fits(w, h);  /* room for ours */
        return hr;
    }

    /* The filling call. Hold back the slots we may need, fill the rest normally. */
    room = ladder_fits(w, h);
    have = *count;
    /* Never write past what the caller allocated. It asked for a count first
     * and this said "that many plus room", but a caller is free to hand back a
     * smaller buffer than it was told about, and appending into one would be a
     * far worse bug than the crash being repaired. */
    if (room > have) room = have;
    *count = have - room;
    hr = real_modelist(self, fmt, flags, count, modes);
    if (FAILED(hr)) { *count = have; return hr; }

    {
        /* Say what is actually on offer, with the right stride. A mode list
         * read at the wrong stride reports resolutions nobody offered, and a
         * conclusion drawn from it is worse than no conclusion. */
        static LONG told;
        UINT tallest = 0, widest = 0;
        for (i = 0; i < *count; ++i)
        {
            const unsigned char *m = (const unsigned char *)modes + (size_t)i * MODE_DESC_SIZE;
            UINT mw = *(const UINT *)(m + 0), mh = *(const UINT *)(m + 4);
            if (mh > tallest) tallest = mh;
            if (mw > widest) widest = mw;
        }
        if (InterlockedIncrement(&told) <= 4)
            logf_("mode list for format %u: %u modes, largest %ux%u; the screen is %ux%u",
                  fmt, *count, widest, tallest, w, h);
    }
    for (i = 0; i < *count; ++i)
    {
        const unsigned char *m = (const unsigned char *)modes + (size_t)i * MODE_DESC_SIZE;
        UINT mw = *(const UINT *)(m + 0), mh = *(const UINT *)(m + 4);
        double aspect;
        if (!mh) continue;
        aspect = (double)mw / (double)mh;
        if (aspect > ASPECT_LOW && aspect < ASPECT_HIGH)
        {
            static LONG said;
            if (InterlockedIncrement(&said) <= 4)
                logf_("        a 16:9 mode is already on offer (%ux%u), adding nothing",
                      mw, mh);
            return hr;
        }
    }
    /* Nothing on offer is 16:9 and this game keeps nothing else, so the array
     * it is about to build would come out empty. Give it the whole ladder that
     * fits, not just enough to survive: the player gets a resolution menu, not
     * a single forced entry. */
    for (i = 0; i < LADDER_N && added < room; ++i)
    {
        unsigned char *m;
        if ((ladder[i].w > w || ladder[i].h > h) && !(added == 0 && i + 1 == LADDER_N))
            continue;
        m = (unsigned char *)modes + (size_t)(*count) * MODE_DESC_SIZE;
        if (*count) memcpy(m, modes, MODE_DESC_SIZE);  /* inherit format and scaling */
        else memset(m, 0, MODE_DESC_SIZE);
        *(UINT *)(m + 0)  = ladder[i].w;
        *(UINT *)(m + 4)  = ladder[i].h;
        *(UINT *)(m + 8)  = hz;
        *(UINT *)(m + 12) = 1;
        *(UINT *)(m + 16) = fmt;
        *count += 1;
        if (!added) { big_w = ladder[i].w; big_h = ladder[i].h; }  /* largest first */
        ++added;
    }
    if (InterlockedIncrement(&modes_added) <= 8)
        logf_("not one of the %u modes on offer is 16:9, and this game keeps "
              "nothing else -- added %u of them, largest %ux%u @ %u Hz",
              *count - added, added, big_w, big_h, hz);
    return hr;
}

static HRESULT WINAPI d3d12_open_shared_handle(void *self, HANDLE handle,
                                               REFIID iid, void **out)
{
    {
        static LONG told;
        if (InterlockedIncrement(&told) <= 12)
            logf_("D3D12 OpenSharedHandle %p %s%s", handle, guid_text_(iid),
                  handle == BRIDGE_HANDLE ? "   << ours" : "");
    }
    if (handle == BRIDGE_HANDLE)
    {
        HRESULT hr;
        if (!out) return E_INVALIDARG;
        *out = NULL;
        if (!IsEqualGUID(iid, &IID_ID3D12Resource)) return E_NOINTERFACE;

        EnterCriticalSection(&frame_lock);
        /* A new clip of another size: the game has made a new texture and is
         * opening it now, so this is the one moment the bridge can change size.
         * Handing back the old one leaves the game drawing from a texture no
         * frame of this clip can be written into. */
        if (bridge_texture && frame_width && frame_height &&
            (texture_width != frame_width || texture_height != frame_height))
        {
            logf_("bridge: the game opens a %ux%u clip on a %ux%u bridge; rebuilding",
                  frame_width, frame_height, texture_width, texture_height);
            bridge_destroy();
        }
        if (!bridge_texture && frame_width && frame_height)
        {
            /*
             * The size the game asked to share, when it said one.
             *
             * The handle it passes belongs to a texture it created itself, and
             * what comes back has to describe that texture -- not the clip.
             * Kingdom Hearts shares a 2048x1080 surface to carry a 1920x1080
             * frame, so a texture built to the clip's size is the wrong
             * resource under the same handle, and what the game copies out of
             * it is not a picture.
             */
            bridge_create((ID3D12Device *)self, frame_width, frame_height);
        }
        hr = bridge_texture ? S_OK : E_FAIL;
        if (bridge_texture)
        {
            ID3D12Resource_AddRef(bridge_texture);
            *out = bridge_texture;
        }
        LeaveCriticalSection(&frame_lock);
        return hr;
    }
    return real_open_shared_handle(self, handle, iid, out);
}

static HRESULT WINAPI res_get_shared_handle(void *self, HANDLE *handle)
{
    HRESULT hr = real_res_get_shared_handle(self, handle);
    {
        static LONG told;
        if (InterlockedIncrement(&told) <= 12)
            logf_("GetSharedHandle -> 0x%08lx%s", (unsigned long)hr,
                  (FAILED(hr) && d3d12_bridge_armed) ? "   (answering BRIDGE_HANDLE)" : "");
    }
    /*
     * Only invent a handle if the side that can recognise it is armed.
     *
     * BRIDGE_HANDLE is meaningful to d3d12_open_shared_handle and to nothing
     * else. Handing it out while that hook is missing turns a clean failure --
     * the game learns it cannot share, and says so -- into a real D3D12 device
     * dereferencing 0xD3D12B21D. Nioh 3 crashed exactly that way, because its
     * D3D12 arrives through Streamline and the hook had not been placed there
     * yet. Reporting the original failure is the safe answer.
     */
    if (FAILED(hr) && handle && d3d12_bridge_armed) { *handle = BRIDGE_HANDLE; return S_OK; }
    return hr;
}
